INSERT INTO `space_versions` (`version`, `title`, `summary`, `created_at`) VALUES
('v80', '去掉聊天框里用不了的按钮', '应用户要求，豆包聊天框工具栏里三个点了只能弹「暂不支持」提示的按钮——云电脑、项目、插件——已直接去掉，不再显示。它们运行在豆包自己的云端环境里，令牌直连协议没有对应开关，空间里本来就用不了。工具栏保留真正能用的：联网搜索开关、技能、模型选择（模型与推理强度）。其余照旧未动：DeepSeek 的快速/专家、深度思考、智能搜索，附件（发图片/文件）与发送按钮都不受影响。', 1795191600000);
